import { useCallback, useMemo, useState, useRef } from 'react'
import { Container } from '../../../../../../components'
import PolicyAddons from '../../../../../../components/PolicyAddons'
import { LANG_STRINGS } from '../../../../../../lang'
import { PolicyEditAddonsStyle } from './index.style'
import get from 'lodash/get'
import { BottomActionContainerStyle } from '../../../../../../commonStyle/index.style'
import ButtonWithIcon from '../../../../../../components/ButtonWithIcon'
import { CALCULATOR_GOLD } from '../../../../../../images'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { CAR_PROTECTION } from '../../../../../../constants/pkgCode'
import isEmpty from 'lodash/isEmpty'

function PolicyAddonsChangeContainer (props) {
  const { location, match, history } = props
  const policyId = useMemo(() => match.params.policyId, [match])
  const applicationData = useMemo(
    () => ((location.state && location.state.applicationDetail) || {}), [location.state]
  )
  const isMVProduct = useMemo(() => (
    get(applicationData.product, 'package.product.code', '') === CAR_PROTECTION),
  [applicationData.product])

  const [{
    CALCULATE_ADDON_PREMIUM_LOADER, GET_PROVIDER_ADDONS_LOADER
  }] = useLoaderContextValue()
  const [isBtnDisable, setBtnDisable] = useState(true)
  const that = useRef({})

  const addonsData = useMemo(() => {
    if (isMVProduct) {
      return {
        data: {
          package_type: get(applicationData, 'product.package.code', ''),
          vehicle_type: get(applicationData, 'policy_detail.vehicle_type', ''),
          brand: get(applicationData, 'policy_detail.brand', ''),
          variant: get(applicationData, 'policy_detail.variant', ''),
          variant_code: get(applicationData, 'policy_detail.variant_code', ''),
          additional_sum_insured: get(applicationData, 'policy_detail.additional_sum_insured', ''),
          year: get(applicationData, 'policy_detail.year', ''),
          model: get(applicationData, 'policy_detail.model', ''),
          region_code: get(applicationData, 'policy_detail.region_code', ''),
          vehicle_sum_insured: get(applicationData, 'policy_detail.vehicle_sum_insured', ''),
          vehicle_plate_no: get(applicationData, 'policy_detail.vehicle_plate_no', ''),
          usage: get(applicationData, 'policy_detail.usage', ''),
          start_date: get(applicationData, 'policy_detail.start_date', ''),
          accessories: get(applicationData, 'policy_detail.accessories', '')
        },
        policyDetail: get(applicationData, 'policy_detail', {}),
        addons: get(applicationData, 'product.add_ons', []),
        addonsCategory: get(applicationData, 'product.add_ons_cat', [])
      }
    }

    return {
      data: {
        occupation_code: get(applicationData, 'policy_detail.occupation_code', ''),
        province_code: get(applicationData, 'policy_detail.province_code', ''),
        sum_insured: get(applicationData, 'policy_detail.sum_insured', ''),
        zone: get(applicationData, 'policy_detail.zone', '')
      },
      policyDetail: get(applicationData, 'policy_detail', {}),
      addons: get(applicationData, 'product.add_ons', []),
      addonsCategory: get(applicationData, 'product.add_ons_cat', [])
    }
  }, [applicationData, isMVProduct])

  const handleChangesInAddon = useCallback((addonData) => {
    // save the addon data on that ref
    that.current = addonData
    if (isBtnDisable) {
      setBtnDisable(false)
    }
  }, [isBtnDisable])

  const handleSave = useCallback(() => {
    // history application data to review and data
    let isAddonsData = false
    for (const key in that.current) {
      const addons = that.current[key]
      if (!isEmpty(addons) && !isAddonsData) {
        isAddonsData = true
        break
      }
    }
    history.push({
      pathname: `/change/policy/addons/review/${policyId}`,
      state: {
        applicationDetail: applicationData,
        addons: isAddonsData ? that.current : {},
        isMVProduct
      }
    })
  }, [history, applicationData, policyId, isMVProduct])

  return (
    <Container
      hideBottomTabs
      loader={GET_PROVIDER_ADDONS_LOADER || CALCULATE_ADDON_PREMIUM_LOADER}
      title={LANG_STRINGS.editAddonsData}
    >
      <PolicyEditAddonsStyle>
        <PolicyAddons
          productId={get(applicationData, 'product.code', '')}
          data={addonsData}
          onChangeAddon={handleChangesInAddon}
          isMVProduct={isMVProduct}
        />
        <BottomActionContainerStyle padding='0'>
          <ButtonWithIcon
            text={LANG_STRINGS.reviewChanges}
            icon={CALCULATOR_GOLD}
            iconRight
            className='bottom-btn'
            disabled={isBtnDisable}
            onClick={handleSave}
          />
        </BottomActionContainerStyle>
      </PolicyEditAddonsStyle>
    </Container>
  )
}

export default PolicyAddonsChangeContainer
